// Panier de la boutique Atelier Morel : totaux, remises et frais de port.
import { arrondir, type Article } from "./prix";

export const SEUIL_PORT_OFFERT = 80;
const FRAIS_PORT = 6.9;

export type Ligne = { article: Article; quantite: number };

export function sousTotal(lignes: Ligne[]): number {
  return lignes.reduce((s, l) => s + l.article.prix * l.quantite, 0);
}

// Remise « printemps » : 10 % dès trois pièces de céramique.
export function remise(lignes: Ligne[]): number {
  const pieces = lignes.filter((l) => l.article.categorie === "ceramique");
  const n = pieces.reduce((s, l) => s + l.quantite, 0);
  return n >= 3 ? sousTotal(pieces) * 0.1 : 0;
}

export function fraisPort(total: number): number {
  return total >= SEUIL_PORT_OFFERT ? 0 : FRAIS_PORT;
}

export function total(lignes: Ligne[]) {
  const st = sousTotal(lignes);
  const r = remise(lignes);
  const port = fraisPort(st - r);
  return {
    sousTotal: arrondir(st),
    remise: arrondir(r),
    port,
    total: arrondir(st - r + port),
  };
}

export function ajouter(lignes: Ligne[], article: Article): Ligne[] {
  const i = lignes.findIndex((l) => l.article.id === article.id);
  if (i === -1) return [...lignes, { article, quantite: 1 }];
  return lignes.map((l, j) => (j === i ? { ...l, quantite: l.quantite + 1 } : l));
}

export function retirer(lignes: Ligne[], id: string): Ligne[] {
  return lignes.filter((l) => l.article.id !== id);
}
